INSERT INTO feature VALUES('equivalences','identity','Equivalences decided by computation (equiv)',NULL,'implemented','notable',NULL,'`equiv(f, g)` certifies two maps mutually inverse by computation, between codes built from units, base atoms, sums, products, lists and data types that do not hold themselves, a data type read constructor by constructor, and a value moves along the equivalence. A function moves along it by its maps, its argument back and its result forward, in the normalizer and the kernel alike, so a structure with operations relates along its carrier''s equivalence, between one type or two.','core-checker core-nbe kernel-core surface-diagnostics','corpus/model/identity/transport-list.gandr corpus/pathological/identity/equiv-list-tail.gandr corpus/model/identity/structure-operations.gandr corpus/model/identity/equiv-data.gandr corpus/pathological/identity/equiv-data.gandr','corpus/model/identity/transport-list.gandr',NULL);
